import React from "react";
import { useCart } from "./GioHang/CartContext";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min.js";

import "./CSS/HomePage.css"
const HomePage = () => {
    const { addToCart } = useCart();

    // Tự động kích hoạt carousel sau khi render
    // useEffect(() => {
    //     const carouselElement = document.querySelector('#carouselExampleAutoplaying');
    //     if (carouselElement) {
    //         new Carousel(carouselElement, {
    //             interval: 3000,
    //             ride: 'carousel'
    //         });
    //     }
    // }, []);


    const categories = [
        { name: "Đồ nam", image: "/assets/doNam.jpg" },
        { name: "Áo thun nam", image: "/assets/AoThun.jpg" },
        { name: "Áo hoodie nam", image: "/assets/AoHodie.jpg" },
        { name: "Đồ nữ", image: "/assets/doNu.jpg" }
    ];

    const products = [
        { id: 1, name: "Sản phẩm 1", price: 250000, image: "/assets/product1.jpg" },
        { id: 2, name: "Sản phẩm 2", price: 300000, image: "/assets/product2.jpg" },
        { id: 3, name: "Sản phẩm 3", price: 200000, image: "/assets/product3.jpg" },
        { id: 4, name: "Sản phẩm 4", price: 400000, image: "/assets/product4.jpg" },
        { id: 5, name: "Sản phẩm 5", price: 350000, image: "/assets/product5.jpg" }
    ];

    return (
        <div className="container mb-4 m-auto mt-5">
            {/* Banner */}
            <div id="carouselExampleAutoplaying" className="carousel slide" data-bs-ride="carousel">
                <div className="carousel-inner rounded">
                    <div className="carousel-item active">
                        <img src="/assets/banner1.jpg" className="d-block w-100" style={{ maxHeight: "400px", objectFit: "cover" }} alt="Banner 1" />
                    </div>
                    <div className="carousel-item">
                        <img src="/assets/banner2.jpg" className="d-block w-100" style={{ maxHeight: "400px", objectFit: "cover" }} alt="Banner 2" />
                    </div>
                    <div className="carousel-item">
                        <img src="/assets/banner3.jpg" className="d-block w-100" style={{ maxHeight: "400px", objectFit: "cover" }} alt="Banner 3" />
                    </div>
                </div>
                <button className="carousel-control-prev" type="button" data-bs-target="#carouselExampleAutoplaying" data-bs-slide="prev">
                    <span className="carousel-control-prev-icon" aria-hidden="true" />
                    <span className="visually-hidden">Previous</span>
                </button>
                <button className="carousel-control-next" type="button" data-bs-target="#carouselExampleAutoplaying" data-bs-slide="next">
                    <span className="carousel-control-next-icon" aria-hidden="true" />
                    <span className="visually-hidden">Next</span>
                </button>
            </div>

            {/* Danh mục nổi bật */}
            <div className="text-center mb-5 mt-5">
                <h2 className="fw-bold text-uppercase">DANH MỤC NỔI BẬT</h2>
                <div className="row mt-4 justify-content-center">
                    {categories.map((cat, idx) => (
                        <div key={idx} className="col-md-3 mb-3">
                            <div className="card h-100 shadow-sm rounded-lg overflow-hidden hover-zoom">
                                <img src={cat.image} className="card-img-top" alt={cat.name} style={{ transition: "transform 0.3s" }} />
                                <div className="card-body text-center">
                                    <h5 className="card-title text-primary">{cat.name}</h5>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Bộ lọc và danh sách sản phẩm */}
            <div className="row justify-content-center">
                {/* Bộ lọc */}
                <div className="col-md-3 mb-4">
                    <div className="border rounded p-3 bg-light shadow-sm">
                        <h5>Chọn khoảng giá</h5>
                        <input type="number" className="form-control mb-2" placeholder="Từ" />
                        <input type="number" className="form-control mb-2" placeholder="Đến" />
                        <button className="btn btn-primary w-100 mb-3">Áp dụng</button>

                        <h5>Chọn danh mục</h5>
                        {["Đồ nam", "Đồ nữ", "Trẻ em"].map((cat, index) => (
                            <div className="form-check" key={index}>
                                <input className="form-check-input" type="checkbox" id={`cat-${index}`} />
                                <label className="form-check-label" htmlFor={`cat-${index}`}>{cat}</label>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Danh sách sản phẩm */}
                <div className="col-md-9">
                    <h4 className="mb-4 text-primary">Có {products.length} sản phẩm được tìm thấy</h4>
                    <div className="row">
                        {products.map((product) => (
                            <div key={product.id} className="col-md-4 mb-4">
                                <div className="card h-100 shadow-sm rounded-lg overflow-hidden hover-shadow">
                                    <img
                                        src={product.image}
                                        className="card-img-top"
                                        alt={product.name}
                                        style={{ height: "200px", objectFit: "cover", transition: "transform 0.3s" }}
                                    />
                                    <div className="card-body text-center">
                                        <h5 className="card-title">{product.name}</h5>
                                        <p className="card-text text-primary fw-bold">
                                            {product.price.toLocaleString()}₫
                                        </p>
                                        <button
                                            className="btn btn-success w-100 rounded-pill shadow-sm"
                                            onClick={() => addToCart(product)}
                                        >
                                            Thêm vào giỏ hàng
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Custom CSS effects */}
            <style>{`
                .hover-zoom img:hover {
                    transform: scale(1.05);
                }
                .hover-shadow:hover {
                    box-shadow: 0 0 20px rgba(0,0,0,0.2);
                    transform: translateY(-5px);
                    transition: all 0.3s ease-in-out;
                }
                .carousel-inner img {
                    transition: transform 0.5s ease;
                }
            `}</style>
        </div>
    );
};

export default HomePage;
